"use strict";(self.webpackChunkultimatelearning=self.webpackChunkultimatelearning||[]).push([[216],{216:a=>{a.exports=JSON.parse('{"topic":{"id":"static-final","title":"Static & Final Keywords","overviewSimple":"Imagine a single chalkboard in a classroom that everyone uses \u2014 that\u2019s static. And imagine a rule written on that board that cannot be erased \u2014 that\u2019s final.","overviewTechnical":["static belongs to the class, not objects.","static variables share memory across all objects.","final variables cannot be changed once assigned.","final methods cannot be overridden.","final classes cannot be inherited."],"story":"A school had a single notice board used by all students. Some rules written on it were permanent and never changed \u2014 exactly like static and final in Java.","realWorldAnalogy":"static = shared Wi-Fi password; final = your birthdate (can\'t change).","keyPoints":["static = class level","final = cannot be modified","static methods access only static data","final classes stop inheritance"],"exampleSimple":"static int count = 0;\\nfinal int MAX = 100;","exampleTechnical":["class Counter {\\n    static int value = 0;\\n    Counter() { value++; }\\n}\\n\\npublic class Main {\\n    public static void main(String[] args) {\\n        new Counter(); new Counter();\\n        System.out.println(Counter.value);\\n    }\\n}","final class Constants {\\n    public static final double PI = 3.14;\\n}\\n\\nclass Test {\\n    public static void main(String[] args) {\\n        System.out.println(Constants.PI);\\n    }\\n}"],"extraNotes":["Static blocks initialize static data.","Final variables must be assigned once.","Static methods cannot use \'this\' keyword."],"bestPracticesSimple":["Use static for shared values","Use final for constants"],"bestPracticesAdvanced":["Use final to create immutable classes","Prefer static factory methods where useful","Avoid overusing static for global state"]}}')}}]);